CREATE TABLE settings(key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at_ms INTEGER NOT NULL);
CREATE TABLE service_preferences(service_id TEXT PRIMARY KEY, vpn_required INTEGER NOT NULL CHECK(vpn_required IN(0,1)), country TEXT, monitor_id TEXT, audio_sink_id TEXT);
CREATE TABLE media_sources(id TEXT PRIMARY KEY, source_type TEXT NOT NULL, root BLOB NOT NULL, volume_identity TEXT, relative_root BLOB, label TEXT NOT NULL, kinds TEXT NOT NULL, availability TEXT NOT NULL, last_seen_ms INTEGER, scanned_at_ms INTEGER);
CREATE TABLE media_items(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES media_sources(id) ON DELETE CASCADE, relative_path BLOB NOT NULL, display_name TEXT NOT NULL, kind TEXT NOT NULL, size INTEGER NOT NULL, mtime_ns TEXT NOT NULL, duration_ms INTEGER, width INTEGER, height INTEGER, metadata_json TEXT NOT NULL DEFAULT '{}', availability TEXT NOT NULL, thumbnail_id TEXT, scan_id TEXT, UNIQUE(source_id,relative_path));
CREATE INDEX media_search ON media_items(kind,display_name COLLATE NOCASE,id);
CREATE TABLE resume_positions(media_id TEXT PRIMARY KEY REFERENCES media_items(id) ON DELETE CASCADE,position_ms INTEGER NOT NULL,duration_ms INTEGER,updated_at_ms INTEGER NOT NULL,completed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE playlists(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at_ms INTEGER NOT NULL,updated_at_ms INTEGER NOT NULL);
CREATE TABLE playlist_items(playlist_id TEXT NOT NULL REFERENCES playlists(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,media_id TEXT NOT NULL REFERENCES media_items(id) ON DELETE CASCADE,PRIMARY KEY(playlist_id,ordinal));
CREATE TABLE thumbnail_entries(cache_key TEXT PRIMARY KEY,media_id TEXT NOT NULL REFERENCES media_items(id) ON DELETE CASCADE,fingerprint TEXT NOT NULL,filename TEXT NOT NULL,bytes INTEGER NOT NULL,last_access_ms INTEGER NOT NULL);
PRAGMA user_version=1;
